+import { Api } from './api';
+import { log } from './log';
+
+/** Approves a pull request once no blocking thread is open on it. */
+export async function approveIfClear(api: Api, pr: number): Promise<void> {
+  let blocking = false;
+  try {
+    blocking = (await api.listOpenBlockers(pr)).length > 0;
+  } catch (error) {
+    log.warning(`Could not list the blockers of #${pr}: ${error}`);
+  }
+  if (!blocking) await api.approve(pr);
+}
